window.ScripturaLexicons.BDAG_PART_0009 = {source:"BDAG", searchAnchorId:"bdag-search-anchor", entryAnchorId:"bdag-entry-anchor", rowsHtml:"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-agridion-bdag\" data-source=\"BDAG\" data-search=\"ἀγρίδιον agridion pequena propriedade fazenda casa campo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀγρίδιον</td><td>Substantivo</td><td>pequena propriedade rural; pequena fazenda</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-agrielaios-adj-bdag\" data-source=\"BDAG\" data-search=\"ἀγριέλαιος agrielaios adjetivo oliveira brava madeira oliveira silvestre BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀγριέλαιος</td><td>Adjetivo</td><td>de oliveira brava; de oliveira silvestre</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-agrielaios-n-bdag\" data-source=\"BDAG\" data-search=\"ἀγριέλαιος agrielaios substantivo oliveira brava silvestre gentios BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀγριέλαιος</td><td>Substantivo</td><td>oliveira brava; oliveira silvestre</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-agrios-bdag\" data-source=\"BDAG\" data-search=\"ἄγριος agrios selvagem silvestre feroz descontrolado tempestuoso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἄγριος</td><td>Adjetivo</td><td>selvagem; silvestre; feroz; tempestuoso</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-agriotes-bdag\" data-source=\"BDAG\" data-search=\"ἀγριότης agriotes selvageria ferocidade BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀγριότης</td><td>Substantivo</td><td>selvageria; ferocidade</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-agrioo-bdag\" data-source=\"BDAG\" data-search=\"ἀγριόω agrioo tornar selvagem ficar descontrolado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀγριόω</td><td>Verbo</td><td>tornar-se selvagem; ficar descontrolado</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-agrippas-bdag\" data-source=\"BDAG\" data-search=\"Ἀγρίππας Agrippas Agripa Herodes Agripa I II BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἀγρίππας</td><td>Nome próprio</td><td>Agripa</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-agros-bdag\" data-source=\"BDAG\" data-search=\"ἀγρός agros campo terra região propriedade fazenda lavoura BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀγρός</td><td>Substantivo</td><td>campo; terra; propriedade rural</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-agrupneo-bdag\" data-source=\"BDAG\" data-search=\"ἀγρυπνέω agrupneo vigiar estar alerta cuidar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀγρυπνέω</td><td>Verbo</td><td>vigiar; estar alerta; cuidar</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-agrupnia-bdag\" data-source=\"BDAG\" data-search=\"ἀγρυπνία agrupnia insônia vigília noites sem dormir cuidado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀγρυπνία</td><td>Substantivo</td><td>insônia; vigília; cuidado</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-ago-bdag\" data-source=\"BDAG\" data-search=\"ἄγω ago conduzir levar trazer prender guiar celebrar ir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἄγω</td><td>Verbo</td><td>conduzir; levar; trazer; guiar; celebrar; ir</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-agoge-bdag\" data-source=\"BDAG\" data-search=\"ἀγωγή agoge conduta modo vida BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀγωγή</td><td>Substantivo</td><td>modo de vida; conduta</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-agon-bdag\" data-source=\"BDAG\" data-search=\"ἀγών agon competição luta combate corrida ansiedade preocupação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀγών</td><td>Substantivo</td><td>competição; luta; combate; preocupação</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-agonia-bdag\" data-source=\"BDAG\" data-search=\"ἀγωνία agonia angústia aflição ansiedade BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀγωνία</td><td>Substantivo</td><td>angústia; aflição; ansiedade</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-agoniao-bdag\" data-source=\"BDAG\" data-search=\"ἀγωνιάω agoniao estar ansioso angustiado aflito BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀγωνιάω</td><td>Verbo</td><td>estar ansioso; angustiar-se</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-agonizomai-bdag\" data-source=\"BDAG\" data-search=\"ἀγωνίζομαι agonizomai competir lutar esforçar-se combate oração BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀγωνίζομαι</td><td>Verbo</td><td>competir; lutar; esforçar-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>", cardsHtml:"<article id=\"entry-agridion-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγρίδιον</h1><div class=\"entry-meta\"><span class=\"greek\">ου, τό</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦agrídion⟧</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Diod S 13, 84, 4; Epict. 2, 22, 10 e outros; M. Ant. 4, 3, 9; Sb 5230, 28 [séc. I d.C.]) <strong>Pequena propriedade rural, pequena fazenda ou casa de campo</strong>, MPol 5:1; 6:1.\n</p></section></article><article id=\"entry-agrielaios-adj-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγριέλαιος</h1><div class=\"entry-meta\"><span class=\"greek\">ον</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦agriélaios⟧</span><span class=\"separator\">·</span><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n<strong>(Que cresce) de uma oliveira brava</strong>, propriamente adjetivo (B-D-F §120, 3; Rob. 168, compare 166) e, portanto, talvez em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.17\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 11.17</a> (como Erycius em <em>Anth. Pal.</em> 9, 237; Ps.-Theocr., <em>Idyll</em> 25, 257). Mas também pode ser tomado como substantivo, como dizemos “carvalho” de um móvel feito dessa madeira (veja o verbete seguinte). — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγρός\" data-meanings=\"campo\">ἀγρός</span>. M-M.\n</p></section></article><article id=\"entry-agrielaios-n-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγριέλαιος</h1><div class=\"entry-meta\"><span class=\"greek\">ου, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦agriélaios⟧</span><span class=\"separator\">·</span><span>substantivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n<strong>Oliveira brava, oliveira silvestre</strong> (Teofrasto, <em>HP</em> 2, 2, 5; Teócrito 7, 18; Nicol. Dam. 90 Fgm. 66, 40 Jac.; PCairZen 184, 7 = PEdgar 100 [= Sb 6815], 7 [255 a.C.]. Como masculino em escólio a Apollon. Rhod. 2, 843, 848–850a; B-D-F §241, 6), figuradamente dos gentios, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.17\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 11.17</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.24\" target=\"_blank\" rel=\"noopener noreferrer\">24</a> (se substantivo; mas veja o verbete precedente; oposto a <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"καλλιέλαιος\" data-meanings=\"oliveira cultivada\">καλλιέλαιος</span>). — T. Fischer, <em>D. Ölbaum</em> 1904; W. Ramsay, “The Olive-Tree and the Wild-Olive”, <em>Exp.</em> 6ª sér., 11, 1905, 16–34; 152–160; E. Fickendey, <em>D. Ölbaum in Kleinasien</em> 1922; S. Linder, “D. Pfropfen m. wilden Ölzweigen (Ro 11:17)”, PJ 26, 1930, 40–43; F. J. Bruijel, “De Olijfboom”, GereformTT 35, 1935, 273–280. — M-M.\n</p></section></article><article id=\"entry-agrios-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄγριος</h1><div class=\"entry-meta\"><span class=\"greek\">ία, ον</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦ágrios⟧</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Homero+; empréstimo no rabínico.)\n<span class=\"sense-number\">1.</span> <strong>Relativo a estar em estado ou condição natural, selvagem, silvestre.</strong> De plantas no campo aberto (Diod S 5, 2, 4; Artem. 4, 57; Jos., <em>Bell.</em> 5, 437; PSI 816, 3 [séc. II a.C.]) Hs 9, 26, 4. De animais (Diod S 4, 17, 4 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ζῷα\" data-meanings=\"animais\">ζῷα</span>; 4, 17, 5 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"θηρία\" data-meanings=\"feras\">θηρία</span>; Arrian, <em>Ind.</em> 11, 11; 13, 1; PSI 406, 42; 409, 18 [séc. III a.C.]; BGU 1252, 4; normalmente LXX; Jos., <em>C. Ap.</em> 2, 139) 1 Cl 56:11 s. (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/JOB.5.22\" target=\"_blank\" rel=\"noopener noreferrer\">Jó 5.22 s.</a>); <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"μέλι ἄ.\" data-meanings=\"mel silvestre\">μέλι ἄ.</span> = <strong>mel de abelhas selvagens</strong> (Iambl. <em>Erot.</em> p. 222, 16 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"μέλιτται ἄγριαι\" data-meanings=\"abelhas selvagens\">μέλιτται ἄγριαι</span> com seu <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"μέλι\" data-meanings=\"mel\">μέλι</span>; Cat. Cod. Astr. X 86b, 6 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγριομέλισσα\" data-meanings=\"abelha selvagem\">ἀγριομέλισσα</span>. Outros pensam em produto vegetal; compare Ps.-Aristot., <em>Mirab.</em> 19; Diod S 19, 94, 10 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"φύεται … ἀπὸ τ. δένδρων μέλι … τὸ καλούμενον ἄγριον\" data-meanings=\"das árvores produz-se mel, chamado silvestre\">φύεται … ἀπὸ τ. δένδρων μέλι … τὸ καλούμενον ἄγριον</span>; Jos., <em>Bell.</em> 4, 468), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3.4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 1.6</a>; GEb 13, 79. Por extensão figurada, de pessoas <strong>selvagens na aparência</strong>: mulheres vestidas de preto, com cabelos soltos, Hs 9, 9, 5; mais plenamente <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄ. τῇ ἰδέᾳ\" data-meanings=\"selvagem na aparência\">ἄ. τῇ ἰδέᾳ</span> de um pastor, 6, 2, 5.\n<span class=\"sense-number\">2.</span> <strong>Relativo a ser indomado ou seguir seu próprio curso, descontrolado</strong>, extensão figurada de 1: de desejos, <strong>selvagem, feroz</strong> (Pla., <em>Rep.</em> 572b), Hm 12, 1, 2; compare 12, 4, 6. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὸ ἄγριον\" data-meanings=\"a ferocidade; crueldade\">τὸ ἄγριον</span> (Pla., <em>Rep.</em> 571c e outros; Herm. Wr. 486, 38; 492, 4 Sc.) IEph 10:2 (oposto a <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἥμερος\" data-meanings=\"manso\">ἥμερος</span>). De fenômenos naturais, <strong>tempestuoso</strong> (Ésquilo, Heródoto e outros): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"κύματα ἄ. θαλάσσης\" data-meanings=\"ondas bravias do mar\">κύματα ἄ. θαλάσσης</span> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/WIS.14.1\" target=\"_blank\" rel=\"noopener noreferrer\">Sb 14.1</a>; SibOr 3, 778) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JUD.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">Jd 13</a>. — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγρός\" data-meanings=\"campo\">ἀγρός</span>. M-M.\n</p></section></article><article id=\"entry-agriotes-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγριότης</h1><div class=\"entry-meta\"><span class=\"greek\">ητος, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦agriótēs⟧</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Xenofonte e outros; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/2MA.15.21\" target=\"_blank\" rel=\"noopener noreferrer\">2 Mc 15.21</a>; TestAbr A 16 p. 97, 1 [Stone p. 42]; 17 p. 99, 4 [Stone p. 46] e outros; Fílon; Jos., <em>Ant.</em> 16, 363 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"θυμὸς καὶ ἀ.\" data-meanings=\"ira e selvageria\">θυμὸς καὶ ἀ.</span>) <strong>Selvageria, ferocidade</strong>, de desejos, Hm 12, 1, 2. — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγρός\" data-meanings=\"campo\">ἀγρός</span>.\n</p></section></article><article id=\"entry-agrioo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγριόω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦agrióō⟧</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(“Tornar selvagem”, trágicos, Xenofonte e outros; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/3MA.5.2\" target=\"_blank\" rel=\"noopener noreferrer\">3 Mc 5.2</a> <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγριωθέντας\" data-meanings=\"tornados selvagens\">ἀγριωθέντας</span>; TestSol 13:5 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἠγριωμέναι\" data-meanings=\"tornadas selvagens\">ἠγριωμέναι</span>). Passivo com sentido ativo, figuradamente, <strong>tornar-se selvagem/descontrolado</strong> de seres humanos, Hs 9, 26, 4 (Diod S 19, 6, 6; Appian, <em>Iber.</em> 96 §417; ativo = “fazer tornar-se selvagem”, TestSim 4:8 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγριοῖ τοῦτο τ. ψυχήν\" data-meanings=\"isto torna a alma selvagem\">ἀγριοῖ τοῦτο τ. ψυχήν</span>). — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγρός\" data-meanings=\"campo\">ἀγρός</span>.\n</p></section></article><article id=\"entry-agrippas-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἀγρίππας</h1><div class=\"entry-meta\"><span class=\"greek\">α, ὁ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦Agríppas⟧</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\nNome de várias figuras políticas: <strong>Agripa</strong> (literatura [Diod S 12, 30, 1; ParJer 3:14; 21:5; 22; GrBar ins. 2; Fílon, Josefo]; inscrições, papiros, moedas; B-D-F §54; 55, 1).\n<span class=\"sense-number\">1.</span> <strong>Herodes Agripa I</strong> (10 a.C.–44 d.C.), filho de Aristóbulo, neto de Herodes, o Grande; primeiro governante (37) de Gaulanítide, Traconítide, Batanéia e Panias, depois (39) também de Abilene, Galileia e Pereia, e finalmente (41) também da Judeia e Samaria; chamado Herodes em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.1\" target=\"_blank\" rel=\"noopener noreferrer\">At 12.1 ss.</a>. — Schürer I 442–454 (fontes e bibliografia); E. Schwartz, NGG 1907, 263 ss.; Rosenberg em Pauly-W. X/1, 1917, 143–146; Meyer III 42 s.; 167 s.; 541 s.\n<span class=\"sense-number\">2.</span> <strong>Herodes Agripa II</strong> (28–92/93 d.C.), filho de 1, governou a tetrarquia de Filipe de 53 até sua morte. Para sua participação no julgamento de Paulo, veja <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.13\" target=\"_blank\" rel=\"noopener noreferrer\">At 25.13 ss.</a> (mencionado <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.13\" target=\"_blank\" rel=\"noopener noreferrer\">25.13</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.22\" target=\"_blank\" rel=\"noopener noreferrer\">22–24</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.26\" target=\"_blank\" rel=\"noopener noreferrer\">26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.1\" target=\"_blank\" rel=\"noopener noreferrer\">26.1 s.</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.7\" target=\"_blank\" rel=\"noopener noreferrer\">7</a> v.l., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.19\" target=\"_blank\" rel=\"noopener noreferrer\">19</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.27\" target=\"_blank\" rel=\"noopener noreferrer\">27 s.</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.32\" target=\"_blank\" rel=\"noopener noreferrer\">32</a>). — Schürer I 471–483 (fontes e bibliografia); E. Schwartz, NGG 1907, 263 ss.; H. Tajra, <em>The Trial of St. Paul</em> 1989, 152–171; Rosenberg em Pauly-W. X/1, 1917, 146–150.\n— Sobre ambos, veja W. Otto e H. Willrich em <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"Ἡρῴδης\" data-meanings=\"Herodes\">Ἡρῴδης</span>, início 3. <strong>Nome de um governador romano</strong>, AcPt Ox 849 recto, 25 s.\n</p></section></article><article id=\"entry-agros-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγρός</h1><div class=\"entry-meta\"><span class=\"greek\">οῦ, ὁ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦agrós⟧</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Compare <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄγω\" data-meanings=\"conduzir\">ἄγω</span>; DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγρός\" data-meanings=\"campo\">ἀγρός</span>; Homero+.) <strong>Campo, terra, região rural.</strong>\n<span class=\"sense-number\">1.</span> <strong>Campo aberto em oposição a cidade ou aldeia, região rural, terra, campo.</strong> Hv 2, 1, 4; 9:3 e outros. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐν (τῷ) ἄγρῳ\" data-meanings=\"no campo\">ἐν (τῷ) ἄγρῳ</span> (PAmh 134, 5; “como gazela em campo aberto”, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/2SA.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">2 Sm 2.18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/2SA.10.8\" target=\"_blank\" rel=\"noopener noreferrer\">10.8</a> e outros) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24.18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.31\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 17.31</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"εἰς τὸν ἀγρόν\" data-meanings=\"para o campo\">εἰς τὸν ἀγρόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 13.16</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"εἶναι ἐν (τῷ) ἀ.\" data-meanings=\"estar no campo\">εἶναι ἐν (τῷ) ἀ.</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.40\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24.40</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 15.25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.35\" target=\"_blank\" rel=\"noopener noreferrer\">17.35</a> v.l.; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἔρχεσθαι εἰς τὸν ἀ.\" data-meanings=\"ir para o campo\">ἔρχεσθαι εἰς τὸν ἀ.</span> Hv 3, 1, 2; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πορεύεσθαι εἰς ἀ.\" data-meanings=\"ir para o campo\">πορεύεσθαι εἰς ἀ.</span> (Timaeus Hist.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/RUT.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rt 2.2</a>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24.18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.16.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 16.12</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὑπάγειν εἰς ἀ.\" data-meanings=\"ir para o campo\">ὑπάγειν εἰς ἀ.</span> Hv 4, 1, 2; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"περιπατεῖν εἰς τὸν ἀ.\" data-meanings=\"andar pelo campo\">περιπατεῖν εἰς τὸν ἀ.</span> Hs 2:1. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἔρχεσθαι ἀπ’ ἀγροῦ\" data-meanings=\"vir do campo\">ἔρχεσθαι ἀπ’ ἀγροῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 15.21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 23.26</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"εἰσέρχεσθαι ἐκ τοῦ ἀ.\" data-meanings=\"entrar vindo do campo\">εἰσέρχεσθαι ἐκ τοῦ ἀ.</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 17.7</a> (compare PEleph 13, 6; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/GEN.30.16\" target=\"_blank\" rel=\"noopener noreferrer\">Gn 30.16</a>; Jos., <em>Ant.</em> 5, 141; B-D-F §255; Mlt. 82); compare <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πάρεστιν ἀπ’ ἀγροῦ\" data-meanings=\"chegou do campo\">πάρεστιν ἀπ’ ἀγροῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 11.6</a> D. — B. 1304.\n<span class=\"sense-number\">2.</span> Frequentemente no plural, <strong>propriedade utilizada para agricultura, fazenda, propriedade rural</strong> (compare lat. <em>ager</em> = propriedade; X., <em>Mem.</em> 3, 9, 11; SIG 914, 39; OGI 235, 2; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/1SA.8.14\" target=\"_blank\" rel=\"noopener noreferrer\">1 Sm 8.14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/1SA.22.7\" target=\"_blank\" rel=\"noopener noreferrer\">22.7</a> e outros; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/JOS.19.6\" target=\"_blank\" rel=\"noopener noreferrer\">Js 19.6</a>; Jos., <em>Ant.</em> 17, 193): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19.29</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.5\" target=\"_blank\" rel=\"noopener noreferrer\">22.5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 10.29 s.</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.18\" target=\"_blank\" rel=\"noopener noreferrer\">14.18</a> (mas veja 3); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.15\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 15.15</a>. Com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πόλις\" data-meanings=\"cidade\">πόλις</span>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀπήγγειλαν εἰς τὴν πόλιν καὶ εἰς τοὺς ἀγρούς\" data-meanings=\"anunciaram na cidade e nas propriedades rurais\">ἀπήγγειλαν εἰς τὴν πόλιν καὶ εἰς τοὺς ἀγρούς</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 5.14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 8.34</a>; com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"κῶμαι\" data-meanings=\"aldeias\">κῶμαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 6.36</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 9.12</a>; com aldeias e cidades, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.56\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 6.56</a>.\n<span class=\"sense-number\">3.</span> <strong>Terra posta sob cultivo, terra arável, campo.</strong> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13.24</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.27\" target=\"_blank\" rel=\"noopener noreferrer\">27</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.31\" target=\"_blank\" rel=\"noopener noreferrer\">31</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.38\" target=\"_blank\" rel=\"noopener noreferrer\">38</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 14.18</a> (veja 2); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.37\" target=\"_blank\" rel=\"noopener noreferrer\">At 4.37</a>; Hv 3, 1, 3. Nele crescem <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὰ κρίνα τοῦ ἀ.\" data-meanings=\"os lírios do campo\">τὰ κρίνα τοῦ ἀ.</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6.28</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"χόρτος τοῦ ἀ.\" data-meanings=\"erva do campo\">χόρτος τοῦ ἀ.</span> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/GEN.3.18\" target=\"_blank\" rel=\"noopener noreferrer\">Gn 3.18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/2KI.19.26\" target=\"_blank\" rel=\"noopener noreferrer\">2 Rs 19.26</a>) v. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.30\" target=\"_blank\" rel=\"noopener noreferrer\">30</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ζιζάνια τοῦ ἀ.\" data-meanings=\"joio do campo\">ζιζάνια τοῦ ἀ.</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.36\" target=\"_blank\" rel=\"noopener noreferrer\">13.36</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"παμβότανον τοῦ ἀ.\" data-meanings=\"toda planta do campo\">παμβότανον τοῦ ἀ.</span> 1 Cl 56:14 (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/JOB.5.25\" target=\"_blank\" rel=\"noopener noreferrer\">Jó 5.25</a>). Usado para esconder tesouro, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.44\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13.44</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀ. τοῦ κεραμέως\" data-meanings=\"campo do oleiro\">ἀ. τοῦ κεραμέως</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27.7 s.</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.10\" target=\"_blank\" rel=\"noopener noreferrer\">10</a> (G. Strecker, <em>Der Weg der Gerechtigkeit</em>, 1962, 76–82). K. Dieterich, RhM 59, 1904, 226 ss. — M-M. TW.\n</p></section></article><article id=\"entry-agrupneo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγρυπνέω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦agrupnéō⟧</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Teógnis e outros; papiros, LXX; JosAs 25:3; Fílon, <em>Aet. M.</em> 70; Tat. 11, 2; literalmente “manter-se desperto, estar acordado”.) Em nossa literatura, figuradamente:\n<span class=\"sense-number\">1.</span> <strong>Estar vigilante diante de perigo ameaçador, estar alerta, manter vigilância, estar de guarda</strong>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγρυπνεῖτε\" data-meanings=\"vigiai; estai alerta\">ἀγρυπνεῖτε</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 13.33</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.36\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 21.36</a> (compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/1ES.8.58\" target=\"_blank\" rel=\"noopener noreferrer\">1 Esd 8.58</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/EZR.8.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ed 8.29</a>).\n<span class=\"sense-number\">2.</span> <strong>Estar atentamente preocupado com, cuidar de</strong> (Plut., <em>Mor.</em> 337b; OGI 521, 6; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/DAN.9.14\" target=\"_blank\" rel=\"noopener noreferrer\">Dn 9.14</a> <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀ. ἐπὶ τὰ κακά\" data-meanings=\"vigiar sobre os males\">ἀ. ἐπὶ τὰ κακά</span>; En 100:8 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀ. νοήσαι τὸ κακόν\" data-meanings=\"estar alerta para perceber o mal\">ἀ. νοήσαι τὸ κακόν</span>): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀ. ὑπὲρ τῶν ψυχῶν\" data-meanings=\"velar pelas almas\">ἀ. ὑπὲρ τῶν ψυχῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.17\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13.17</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"εἰς αὐτό\" data-meanings=\"para isto\">εἰς αὐτό</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 6.18</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀ. οὐκ εἰς τὸ ἀγαθὸν ἀλλ’ εἰς τὸ πονηρόν\" data-meanings=\"vigiar não para o bem, mas para o mal\">ἀ. οὐκ εἰς τὸ ἀγαθὸν ἀλλ’ εἰς τὸ πονηρόν</span> D 5:2; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οὐκ εἰς φόβον θεοῦ ἀλλὰ ἐπὶ τὸ πονηρόν\" data-meanings=\"não para o temor de Deus, mas para o mal\">οὐκ εἰς φόβον θεοῦ ἀλλὰ ἐπὶ τὸ πονηρόν</span> <span class=\"biblio-ref tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"biblio\" data-tooltip-label=\"B 20:2\" data-tooltip-text=\"Epístola de Barnabé 20:2\">B 20:2</span>. — G. Theissen, <em>Sociology of Early Christianity</em>, trad. J. Bowden, 1978. DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγρός\" data-meanings=\"campo\">ἀγρός</span>. M-M. TW.\n</p></section></article><article id=\"entry-agrupnia-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγρυπνία</h1><div class=\"entry-meta\"><span class=\"greek\">ας, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦agrupnía⟧</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Veja <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγρυπνέω\" data-meanings=\"vigiar; estar desperto\">ἀγρυπνέω</span>; Heródoto e outros; BGU 1764, 9 [séc. I a.C.]; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/SIR.31.2\" target=\"_blank\" rel=\"noopener noreferrer\">Eclo 31.2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/SIR.38.26\" target=\"_blank\" rel=\"noopener noreferrer\">38.26</a> e outros; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/2MA.2.26\" target=\"_blank\" rel=\"noopener noreferrer\">2 Mc 2.26</a>; TestSol 18:32; Jos., <em>Bell.</em> 3, 318.)\n<span class=\"sense-number\">1.</span> <strong>Estado de permanecer acordado por não conseguir dormir, insônia</strong>, literalmente, apenas plural (SIG 1169, 50): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐν ἀγρυπνίαις\" data-meanings=\"em noites sem dormir; em vigílias\">ἐν ἀγρυπνίαις</span>, “com noites sem dormir” (e outras dificuldades, como X., <em>Mem.</em> 4, 5, 9; Plut., <em>Mor.</em> 135e; <em>Sertor.</em> 574 [13, 2] <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πόνοι, ὁδοιπορίαι, ἀγρυπνίαι\" data-meanings=\"fadigas, jornadas, noites sem dormir\">πόνοι, ὁδοιπορίαι, ἀγρυπνίαι</span>; <em>Sulla</em> 470 [28, 14] <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγρυπνίαι κ. κόποι\" data-meanings=\"vigílias e fadigas\">ἀγρυπνίαι κ. κόποι</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.6.5\" target=\"_blank\" rel=\"noopener noreferrer\">2 Co 6.5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.27\" target=\"_blank\" rel=\"noopener noreferrer\">11.27</a>. Sobre a figura retórica “perístase”, veja A. Fridrichsen, SymbOsl 7 (1928), 25–29; 8 (1929), 78–82; K. Hum. Vetensk.-Samfundet i Upps. Årsbok 1943, 31–34; Danker, <em>Benefactor</em> 363–364; <em>Augsburg Comm.: 2 Cor</em> 1989, 89–91.\n<span class=\"sense-number\">2.</span> <strong>Estado de estar atentamente preocupado, cuidado</strong>, extensão figurada de 1 (SEG VIII 548, 30 [séc. I a.C.]; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/SIR.42.9\" target=\"_blank\" rel=\"noopener noreferrer\">Eclo 42.9</a>, a ponto de causar perda de sono), <span class=\"biblio-ref tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"biblio\" data-tooltip-label=\"B 21:7\" data-tooltip-text=\"Epístola de Barnabé 21:7\">B 21:7</span> (com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐπιθυμία\" data-meanings=\"desejo\">ἐπιθυμία</span>; mas o contexto não sugere insônia). — M-M. TW. Sv.\n</p></section></article><article id=\"entry-ago-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄγω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦ágō⟧</span><span class=\"separator\">·</span><span class=\"greek\">fut. ἄξω; 2 aor. ἤγαγον; 3 pl. ἤγαγαν; ἠγάγοσαν LXX; pf. ἀγήοχα · pass. impf. ἠγόμην; fut. ἀχθήσομαι; 1 aor. ἤχθην; pf. ἦκται</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἤγαγαν\" data-meanings=\"levaram; conduziram\">ἤγαγαν</span> GJs 10:1; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἠγάγοσαν\" data-meanings=\"levaram; forma helenística\">ἠγάγοσαν</span> LXX; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγήοχα\" data-meanings=\"tenho conduzido; perfeito\">ἀγήοχα</span> LXX; passivo <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἦκται\" data-meanings=\"foi levado\">ἦκται</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/ISA.23.1\" target=\"_blank\" rel=\"noopener noreferrer\">Is 23.1</a>. Veja o imperativo presente ativo <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄγε\" data-meanings=\"vem! vamos!\">ἄγε</span> como verbete separado. (Homero+.)\n<span class=\"sense-number\">1.</span> <strong>Dirigir o movimento de um objeto de uma posição a outra.</strong>\n<strong>a.</strong> <strong>Conduzir, trazer, levar, levar embora</strong>, com acusativo: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὴν ὄνον καὶ τὸν πῶλον\" data-meanings=\"a jumenta e o jumentinho\">τὴν ὄνον καὶ τὸν πῶλον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21.7</a> (compare Just., <em>A</em> I, 32, 6; 54, 7); <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"γυναῖκα\" data-meanings=\"mulher\">γυναῖκα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.3\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 8.3</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"παῖδα\" data-meanings=\"jovem; rapaz\">παῖδα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.12\" target=\"_blank\" rel=\"noopener noreferrer\">At 20.12</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄγαγε αὐτήν\" data-meanings=\"traze-a\">ἄγαγε αὐτήν</span> AcPl Ha 2, 15 s.; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"θέλεις χαλκέα ἄγωμεν;\" data-meanings=\"queres que tragamos um ferreiro/serralheiro?\">θέλεις χαλκέα ἄγωμεν;</span> 3, 5. Com acusativo e meta: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πρὸς αὐτόν\" data-meanings=\"até ele\">πρὸς αὐτόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.40\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 4.40</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.40\" target=\"_blank\" rel=\"noopener noreferrer\">18.40</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.35\" target=\"_blank\" rel=\"noopener noreferrer\">19.35</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.13\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 9.13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.27\" target=\"_blank\" rel=\"noopener noreferrer\">At 9.27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.18\" target=\"_blank\" rel=\"noopener noreferrer\">23.18</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πρὸς τὸ συμψέλιον\" data-meanings=\"para o banco\">πρὸς τὸ συμψέλιον</span>, Hv 3, 1, 7; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"εἰς τὴν ἔρημον\" data-meanings=\"para o deserto\">εἰς τὴν ἔρημον</span> <span class=\"biblio-ref tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"biblio\" data-tooltip-label=\"B 7:8\" data-tooltip-text=\"Epístola de Barnabé 7:8\">B 7:8</span>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐπὶ σφαγήν\" data-meanings=\"para o abate\">ἐπὶ σφαγήν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.32\" target=\"_blank\" rel=\"noopener noreferrer\">At 8.32</a>; 1 Cl 16:7; <span class=\"biblio-ref tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"biblio\" data-tooltip-label=\"B 5:2\" data-tooltip-text=\"Epístola de Barnabé 5:2\">B 5:2</span> (os três, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/ISA.53.7\" target=\"_blank\" rel=\"noopener noreferrer\">Is 53.7</a>); <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἔξω\" data-meanings=\"para fora\">ἔξω</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.4\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 19.4</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.13\" target=\"_blank\" rel=\"noopener noreferrer\">13</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὧδε\" data-meanings=\"aqui\">ὧδε</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 19.27</a>. Com dativo de pessoa: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγάγετέ μοι\" data-meanings=\"trazei-me\">ἀγάγετέ μοι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21.2</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τινὰ σύν τινι\" data-meanings=\"levar alguém com alguém\">τινὰ σύν τινι</span> (compare PGM 1, 179) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.14\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ts 4.14</a>. Passivo: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὸ πλοῖον ἀγόμενον εἰς Μακεδονίαν\" data-meanings=\"o navio seguindo para a Macedônia\">τὸ πλοῖον ἀγόμενον εἰς Μακεδονίαν</span> AcPl Ha 5, 15. Em sentido transferido, de Jesus como pastor, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.16\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 10.16</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὁ θεὸς ἤγαγεν τῷ Ἰσραὴλ σωτῆρα Ἰησοῦν\" data-meanings=\"Deus trouxe a Israel Jesus como Salvador\">ὁ θεὸς ἤγαγεν τῷ Ἰσραὴλ σωτῆρα Ἰησοῦν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.23\" target=\"_blank\" rel=\"noopener noreferrer\">At 13.23</a>.\n<strong>b.</strong> <strong>Levar consigo, conduzir junto</strong> (Jos., <em>Ant.</em> 10, 179): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"εἰς Ἀντιόχειαν\" data-meanings=\"para Antioquia\">εἰς Ἀντιόχειαν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.11.26\" target=\"_blank\" rel=\"noopener noreferrer\">At 11.26</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἕως Ἀθηνῶν\" data-meanings=\"até Atenas\">ἕως Ἀθηνῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.15\" target=\"_blank\" rel=\"noopener noreferrer\">17.15</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐπὶ τὸν Ἄρειον πάγον\" data-meanings=\"ao Areópago\">ἐπὶ τὸν Ἄρειον πάγον</span> v. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.19\" target=\"_blank\" rel=\"noopener noreferrer\">19</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄγοντες παρ’ ᾧ ξενισθῶμεν Μνάσωνι\" data-meanings=\"levando-nos a Mnasom, com quem nos hospedaríamos\">ἄγοντες παρ’ ᾧ ξενισθῶμεν Μνάσωνι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.16\" target=\"_blank\" rel=\"noopener noreferrer\">21.16</a> (veja <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ξενίζω\" data-meanings=\"hospedar\">ξενίζω</span> e B-D-F §294, 5; Rob. 719); <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄγε μετὰ σεαυτοῦ\" data-meanings=\"traze-o contigo\">ἄγε μετὰ σεαυτοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Tm 4.11</a> (PPetr II 32 [2a], 13).\n<span class=\"sense-number\">2.</span> <strong>Tomar sob custódia, levar, prender</strong>, termo jurídico, com acusativo: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 13.11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.54\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 22.54</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.45\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 7.45</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.26\" target=\"_blank\" rel=\"noopener noreferrer\">At 5.26</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὅπως δεδεμένους ἀγάγῃ εἰς Ἰερουσαλήμ\" data-meanings=\"para levar presos a Jerusalém\">ὅπως δεδεμένους ἀγάγῃ εἰς Ἰερουσαλήμ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.2\" target=\"_blank\" rel=\"noopener noreferrer\">At 9.2</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.22.5\" target=\"_blank\" rel=\"noopener noreferrer\">22.5</a>. De apresentação a julgamento, com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐπί\" data-meanings=\"diante de; perante\">ἐπί</span> + acusativo: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐπὶ ἡγεμόνας\" data-meanings=\"diante de governadores\">ἐπὶ ἡγεμόνας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10.18</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐπὶ τὸ βῆμα\" data-meanings=\"ao tribunal\">ἐπὶ τὸ βῆμα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.12\" target=\"_blank\" rel=\"noopener noreferrer\">At 18.12</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐπ’ ἐξουσίαν\" data-meanings=\"diante da autoridade\">ἐπ’ ἐξουσίαν</span> Hs 9, 28, 4; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"εἰς τὸ συνέδριον\" data-meanings=\"ao Sinédrio\">εἰς τὸ συνέδριον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.6.12\" target=\"_blank\" rel=\"noopener noreferrer\">At 6.12</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"[εἰς τὸ συμ]β[ο]ύλιον\" data-meanings=\"ao conselho\">[εἰς τὸ συμ]β[ο]ύλιον</span> AcPl BMM verso 20. Absoluto, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.6\" target=\"_blank\" rel=\"noopener noreferrer\">At 25.6</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.17\" target=\"_blank\" rel=\"noopener noreferrer\">17</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.23\" target=\"_blank\" rel=\"noopener noreferrer\">23</a>. Transporte de prisioneiro, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.31\" target=\"_blank\" rel=\"noopener noreferrer\">At 23.31</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.28\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 18.28</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"εἰς τὴν παρεμβολήν\" data-meanings=\"para o quartel\">εἰς τὴν παρεμβολήν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.34\" target=\"_blank\" rel=\"noopener noreferrer\">At 21.34</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.10\" target=\"_blank\" rel=\"noopener noreferrer\">23.10</a>. Levar para execução, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.32\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 23.32</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.16\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 19.16</a> v.l.; veja <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀπάγω\" data-meanings=\"levar embora\">ἀπάγω</span> 2c.\n<span class=\"sense-number\">3.</span> <strong>Conduzir/guiar moral ou espiritualmente, levar, encorajar [em direção a]</strong>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τινὰ εἰς μετάνοιαν\" data-meanings=\"conduzir alguém ao arrependimento\">τινὰ εἰς μετάνοιαν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 2.4</a> (Polyb. 5, 16, 2; EpArist 188; Jos., <em>Ant.</em> 4, 144); <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"εἰς δόξαν\" data-meanings=\"à glória\">εἰς δόξαν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2.10</a>; do ciúme, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄ. εἰς θάνατον\" data-meanings=\"conduzir à morte\">ἄ. εἰς θάνατον</span> 1 Cl 9:1; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"γυναικάρια ἀγόμενα ἐπιθυμίαις ποικίλαις\" data-meanings=\"mulherzinhas levadas por vários desejos\">γυναικάρια ἀγόμενα ἐπιθυμίαις ποικίλαις</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">2 Tm 3.6</a> (paralelos em Aristóteles, Eurípides, Platão, Demóstenes, Parthenius e Mel., <em>P.</em> 50, 359). Frequentemente da ação do Espírito sobre seres humanos: passivo, <strong>ser guiado, deixar-se guiar</strong>, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πνεύματι θεοῦ ἄγεσθαι\" data-meanings=\"ser guiado pelo Espírito de Deus\">πνεύματι θεοῦ ἄγεσθαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.14\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 8.14</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.18\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 5.18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 4.1</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.9\" target=\"_blank\" rel=\"noopener noreferrer\">9</a> (sobre o “passivo permissivo”, Gildersleeve, <em>Syntax</em> I §167). — <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 12.2</a> é difícil: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὅτι πρὸς τὰ εἴδωλα τὰ ἄφωνα ὡς ἂν ἤγεσθε ἀπαγόμενοι\" data-meanings=\"como éreis levados, repetidamente arrastados para os ídolos mudos\">ὅτι πρὸς τὰ εἴδωλα τὰ ἄφωνα ὡς ἂν ἤγεσθε ἀπαγόμενοι</span> pode ser traduzido “como éreis atraídos, repetidamente levados aos ídolos mudos”, onde <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄν\" data-meanings=\"partícula modal\">ἄν</span> marca repetição e <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὡς\" data-meanings=\"como\">ὡς</span> retoma o precedente <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὅτι\" data-meanings=\"que\">ὅτι</span>; para outra explicação, pressupondo <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὡς ἀνήγεσθε\" data-meanings=\"como éreis conduzidos para cima\">ὡς ἀνήγεσθε</span>, veja J. Weiss ad loc. e ICC ad loc. [Paralelos: Psellus; Herodas; CB I/2, 390 nº 248.] <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"[τ]ὰς ἐπὶ τὴν ἀπάτην ἀγούσας\" data-meanings=\"[caminhos] que conduzem ao engano\">[τ]ὰς ἐπὶ τὴν ἀπάτην ἀγούσας</span> AcPl Ha 1, 13.\n<span class=\"sense-number\">4.</span> <strong>Empregar tempo para um propósito específico, passar, observar, celebrar</strong> (Eurípides, Heródoto+; inscrição de Abércio 18; LXX): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀ. τὴν ἡμέραν τὴν ὀγδόην εἰς εὐφροσύνην\" data-meanings=\"celebrar o oitavo dia para alegria\">ἀ. τὴν ἡμέραν τὴν ὀγδόην εἰς εὐφροσύνην</span>, “celebrar o oitavo dia como festa de alegria”, <span class=\"biblio-ref tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"biblio\" data-tooltip-label=\"B 15:9\" data-tooltip-text=\"Epístola de Barnabé 15:9\">B 15:9</span> (compare OGI 90, 47; PCairGoodsp 3, 18; frequente em PCairZen). Talvez impessoal: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τρίτην ταύτην ἡμέραν ἄγει\" data-meanings=\"este é o terceiro dia\">τρίτην ταύτην ἡμέραν ἄγει</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 24.21</a>; mas, como a expressão não se encontra em outro lugar, é provavelmente melhor suprir <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"Ἰησοῦς\" data-meanings=\"Jesus\">Ἰησοῦς</span> como sujeito (B-D-F §129), literalmente “Jesus está passando o terceiro dia” (paralelos em Galeno). De festas, <strong>celebrar, observar</strong>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"γενέσια\" data-meanings=\"aniversário\">γενέσια</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14.6</a> v.l.; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὸ σάββατον\" data-meanings=\"o sábado\">τὸ σάββατον</span> PtK 2 p. 14, 28; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"νεομηνίαν\" data-meanings=\"lua nova\">νεομηνίαν</span> ibid. linha 29. De reuniões: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"συμβούλιον ἄγειν\" data-meanings=\"realizar uma reunião/conselho\">συμβούλιον ἄγειν</span> IPol 7:2. Passivo <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγοραῖοι ἄγονται\" data-meanings=\"os tribunais estão em sessão\">ἀγοραῖοι ἄγονται</span> (veja <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγοραῖος\" data-meanings=\"relativo ao mercado; sessão judicial\">ἀγοραῖος</span> 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.38\" target=\"_blank\" rel=\"noopener noreferrer\">At 19.38</a>.\n<span class=\"sense-number\">5.</span> <strong>Afastar-se de uma posição, ir</strong>, intransitivo (Xenofonte e outros): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄγωμεν\" data-meanings=\"vamos\">ἄγωμεν</span> (assim <em>Vi. Aesopi</em> G 77 P.; empréstimo no rabínico; B-D-F §308) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.46\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26.46</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.42\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 14.42</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.16\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 11.16</a>. Com meta: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"εἰς τὰς κωμοπόλεις\" data-meanings=\"às vilas\">εἰς τὰς κωμοπόλεις</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.38\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 1.38</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"εἰς τὴν Ἰουδαίαν\" data-meanings=\"à Judeia\">εἰς τὴν Ἰουδαίαν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.7\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 11.7</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"εἰς τὸ ὄρος\" data-meanings=\"ao monte\">εἰς τὸ ὄρος</span> ApcPt 2:4; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"εἰς ἀγρόν\" data-meanings=\"ao campo\">εἰς ἀγρόν</span> Hs 6, 1, 5; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐπὶ τὴν θεωρίαν\" data-meanings=\"ao espetáculo\">ἐπὶ τὴν θεωρίαν</span> AcPl Ha 4, 7; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πρὸς αὐτόν\" data-meanings=\"até ele\">πρὸς αὐτόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.15\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 11.15</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"παρὰ τὸν πύργον\" data-meanings=\"junto à torre\">παρὰ τὸν πύργον</span> Hs 9, 5, 6; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄγωμεν ἴδωμεν τὸν ἔχοντα τὸν θεὸν θηριομαχοῦντα\" data-meanings=\"vamos ver o homem que possui Deus lutar com as feras\">ἄγωμεν ἴδωμεν τὸν ἔχοντα τὸν θεὸν θηριομαχοῦντα</span> AcPl Ha 4, 7. Com ponto de partida, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐντεῦθεν\" data-meanings=\"daqui\">ἐντεῦθεν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.14.31\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 14.31</a>. — J. Fitzmyer, “The Use of Agein and Pherein in the Synoptics”, <em>Gingrich Festschr.</em> 147–160. — B. 711; 713. DELG. M-M.\n</p></section></article><article id=\"entry-agoge-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγωγή</h1><div class=\"entry-meta\"><span class=\"greek\">ῆς, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦agōgḗ⟧</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Ésquilo, Heródoto e outros; inscrições, papiros, LXX.) “Condução” (Orígenes, <em>C. Cels.</em> 3, 73, 12), depois <strong>modo de vida, conduta</strong> (X., <em>Eq.</em> 3, 4; Polyb. 4, 74, 1; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀ. τοῦ βίου\" data-meanings=\"modo de vida\">ἀ. τοῦ βίου</span>; Diod S 13, 82, 7; M. Ant. 1, 6; IMagnMai 164, 3 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἤθει καὶ ἀγωγῇ κόσμιον\" data-meanings=\"disciplinado em caráter e conduta\">ἤθει καὶ ἀγωγῇ κόσμιον</span>; OGI 223, 15 [séc. III a.C.]; 474, 9; 485, 3; UPZ 113, 12 [156 a.C.]; PTebt 24, 57 [117 a.C.]; SB 9050 V, 11 s. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἡ τοῦ βίου ἀ.\" data-meanings=\"o modo de vida\">ἡ τοῦ βίου ἀ.</span>; PPrinc 75, 5; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/EST.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">Et 2.20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/2MA.11.24\" target=\"_blank\" rel=\"noopener noreferrer\">2 Mc 11.24</a>; EpArist; Fílon; Jos., <em>Ant.</em> 14, 195; Iren. 4, 38, 1; Orígenes, <em>C. Cels.</em> 3, 51, 16; veja Nägeli 34), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Tm 3.10</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἡ ἐν Χριστῷ ἀ.\" data-meanings=\"o modo de vida em Cristo\">ἡ ἐν Χριστῷ ἀ.</span>, “o modo de vida cristão”, 1 Cl 47:6 (v.l. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγάπε\" data-meanings=\"amor; forma variante citada\">ἀγάπε</span>); <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"σεμνὴ … ἁγνὴ ἀ.\" data-meanings=\"conduta digna … pura\">σεμνὴ … ἁγνὴ ἀ.</span> 48:1. — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄγω\" data-meanings=\"conduzir\">ἄγω</span> 18. TW. Sv.\n</p></section></article><article id=\"entry-agon-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγών</h1><div class=\"entry-meta\"><span class=\"greek\">ἀγῶνος, ὁ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦agṓn⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Com muitos sentidos desde Homero; inscrições, papiros, LXX; EpArist 14; Fílon; Jos., <em>Ant.</em> 17, 92; 185 e outros; Just., <em>D.</em> 142, 2; Tat. 12, 4; empréstimo no rabínico.) Em nossa literatura, somente figuradamente.\n<span class=\"sense-number\">1.</span> O sentido de <strong>“competição atlética”</strong> é transferido ao domínio moral e espiritual: <strong>competição, combate, corrida</strong> (compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/WIS.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">Sb 4.2</a>): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τρέχωμεν τὸν προκείμενον ἡμῖν ἀγῶνα\" data-meanings=\"corramos a corrida que está diante de nós\">τρέχωμεν τὸν προκείμενον ἡμῖν ἀγῶνα</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.1\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12.1</a> (compare Eur., <em>Or.</em> 847; Hdt. 9, 60, 1 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγῶνος μεγίστου προκειμένου\" data-meanings=\"estando proposta uma grande competição\">ἀγῶνος μεγίστου προκειμένου</span>; 7, 11, 3; Lucian, <em>Anach.</em> 15; Epict. 3, 25, 3; Hdt. 8, 102, 3 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πολλοὺς ἀγῶνας δραμέονται οἱ Ἕλληνες\" data-meanings=\"os gregos correrão muitas competições\">πολλοὺς ἀγῶνας δραμέονται οἱ Ἕλληνες</span>; Dionys. Hal. 7, 48). Compare 1 Cl 7:1; GJs 20:1.\n<span class=\"sense-number\">2.</span> Em geral, <strong>luta contra oposição, luta, combate</strong> (Iren. 5, 29, 1; Hippol., <em>Ref.</em> 9, 6; Orig., <em>C. Cels.</em> 1, 22, 18; Did., <em>Gen.</em> 250, 29): pelo evangelho, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.30\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 1.30</a>; e na atividade a seu serviço, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐν πολλῷ ἀ.\" data-meanings=\"em grande luta\">ἐν πολλῷ ἀ.</span> = “sob grande tensão / diante de grande oposição”, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ts 2.2</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀ. ἀγωνίζομαι\" data-meanings=\"lutar uma luta; combater um combate\">ἀ. ἀγωνίζομαι</span> (Socrat., <em>Ep.</em> 14, 4; Epict. 1, 9, 12; Appian, <em>Bell. Civ.</em> 1, 110 §515; SIG 434/5, 10; IBM III, 604, 7 s.; Fílon; Herm. Wr. 10, 19a), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Tm 6.12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Tm 4.7</a> (compare Thuc. 7, 68, 3 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"καλὸς ὁ ἀ.\" data-meanings=\"belo/nobre é o combate\">καλὸς ὁ ἀ.</span>; Synes., <em>Ad Paeon.</em> 3, 309c; J. Barton, “Bonum certamen certavi”, <em>Biblica</em> 40, 1959, 878–884). <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὁ τῆς ἀφθαρσίας ἀ.\" data-meanings=\"o combate da incorruptibilidade\">ὁ τῆς ἀφθαρσίας ἀ.</span> 2 Cl 7:5; também <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄφθαρτος ἀ.\" data-meanings=\"combate incorruptível\">ἄφθαρτος ἀ.</span> v. 3, oposto a <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"φθαρτὸς ἀ.\" data-meanings=\"combate corruptível\">φθαρτὸς ἀ.</span> vv. 1, 4 (veja <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"καταπλέω\" data-meanings=\"navegar para terra; chegar ao porto\">καταπλέω</span>).\n— Também <strong>ansiedade, preocupação</strong> (Eur., <em>Phoen.</em> 1350; Thuc. 7, 71, 1; Polyb. 4, 56, 4; Plut., <em>Tit. Flamin.</em> 378 [16, 1] <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγῶνα καὶ πόνον\" data-meanings=\"ansiedade e sofrimento\">ἀγῶνα καὶ πόνον</span>; PHeid 228, 14 [séc. III a.C.]; BGU 1139, 17; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/ISA.7.13\" target=\"_blank\" rel=\"noopener noreferrer\">Is 7.13</a>): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὑπέρ τινος\" data-meanings=\"por alguém; acerca de alguém\">ὑπέρ τινος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 2.1</a>; compare 1 Cl 2:4.\n— F. Dölger, <em>Ac</em> II 1930, 294 ss.; III 1932, 177 ss.; J. Jüthner, RAC I, 188 s.; V. Pfitzner, <em>Paul and the Agon Motif: Traditional Athletic Imagery in the Pauline Literature</em>, 1967. — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄγω\" data-meanings=\"conduzir\">ἄγω</span>. M-M. TW. Spicq. Sv.\n</p></section></article><article id=\"entry-agonia-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγωνία</h1><div class=\"entry-meta\"><span class=\"greek\">ας, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦agōnía⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Píndaro, Heródoto e outros escritores antigos = <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγών\" data-meanings=\"competição; luta\">ἀγών</span>; assim também <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"δι’ ὅπλων ἀγωνίας\" data-meanings=\"competições com armas\">δι’ ὅπλων ἀγωνίας</span> Ath. 35, 1.) Em época posterior — mudança semelhante ocorreu com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγωνιάω\" data-meanings=\"estar angustiado; ansioso\">ἀγωνιάω</span> — <strong>apreensão da mente, especialmente diante de males iminentes, aflição, angústia</strong> (ansiedade de intensidade variável: Hyperid., Fgm. 203; Demosth. 18, 33 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"φόβος καὶ ἀ.\" data-meanings=\"medo e angústia\">φόβος καὶ ἀ.</span>; PHib 186, 31 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πόνος καὶ ἀγωνία\" data-meanings=\"sofrimento e angústia\">πόνος καὶ ἀγωνία</span>; especialmente entre estoicos, espécie de <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"φόβος\" data-meanings=\"medo\">φόβος</span>; com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"λύπη\" data-meanings=\"tristeza\">λύπη</span> como expressão de <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλγηδών\" data-meanings=\"dor\">ἀλγηδών</span> em Crisipo, Stoic. II 248, 16; Epict. 2, 13, 10; escólio a Apollon. Rhod. 3, 471; BGU 884 I, 6; PTebt 423, 13 s.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/2MA.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">2 Mc 3.14</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/2MA.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">16</a>; Fílon; Jos., <em>Bell.</em> 4, 90; <em>Ant.</em> 11, 326 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἦν ἐν ἀγωνίᾳ κ. δέει\" data-meanings=\"estava em angústia e temor\">ἦν ἐν ἀγωνίᾳ κ. δέει</span>; Iren. 1, 4, 4): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"γενόμενος ἐν ἀ.\" data-meanings=\"estando em angústia\">γενόμενος ἐν ἀ.</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.44\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 22.44</a>. — J. Neyrey, <em>Biblica</em> 61, 1980, 159–165 (ἀγωνία como luta vitoriosa); Field, <em>Notes</em> 77 s. — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄγω\" data-meanings=\"conduzir\">ἄγω</span>. M-M. TW.\n</p></section></article><article id=\"entry-agoniao-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγωνιάω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦agōniáō⟧</span><span class=\"separator\">·</span><span class=\"greek\">impf. ἠγωνίων; 1 aor. ptc. ἀγωνιάσας; inf. ἀγωνιᾶσαι</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγωνιάσας\" data-meanings=\"tendo-se angustiado\">ἀγωνιάσας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/EST.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">Et 5.1e</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγωνιᾶσαι\" data-meanings=\"estar angustiado; preocupar-se\">ἀγωνιᾶσαι</span> Just., <em>A</em> I, 4, 2.) <strong>Estar ansioso, estar angustiado</strong> (assim em escritores posteriores, inclusive Dio Chrys. 4, 55, com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"μή\" data-meanings=\"que não; para que não\">μή</span> seguinte; inscrições, papiros; LXX; Jos., <em>Ant.</em> 9, 32): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγωνιῶντες μεγάλως\" data-meanings=\"estando em grande ansiedade\">ἀγωνιῶντες μεγάλως</span>, “cheios de grande ansiedade” (PGiss 19, 3; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/2MA.3.21\" target=\"_blank\" rel=\"noopener noreferrer\">2 Mc 3.21</a>; compare <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"συναγωνιάω\" data-meanings=\"estar em suspense temeroso\">συναγωνιάω</span> Polyb. 3, 43, 7; 8), GPt 11:45; seguido de pergunta indireta com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"μήποτε\" data-meanings=\"se por acaso; para que não\">μήποτε</span> (UPZ 62, 30 [161/160 a.C.]; com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"μή\" data-meanings=\"que não\">μή</span> Just., <em>A</em> I, 4, 2), 5:15. Seguido de genitivo absoluto: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οὐ γὰρ μικρῶς ἀγωνιῶ τοιούτου σου ὄντος\" data-meanings=\"não estou pouco preocupado, vendo-te assim\">οὐ γὰρ μικρῶς ἀγωνιῶ τοιούτου σου ὄντος</span>, AcPl Ha 7, 31. — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄγω\" data-meanings=\"conduzir\">ἄγω</span>.\n</p></section></article><article id=\"entry-agonizomai-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγωνίζομαι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦agōnízomai⟧</span><span class=\"separator\">·</span><span class=\"greek\">impf. ἠγωνιζόμην; fut. ἀγωνίσομαι / ἀγωνιοῦμαι; 1 aor. ἠγωνισάμην; pf. ἠγώνισμαι</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Eurípides, Heródoto+.)\n<span class=\"sense-number\">1.</span> De competição atlética, literal e figuradamente, <strong>participar de uma competição, competir</strong>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πᾶς ὁ ἀγωνιζόμενος\" data-meanings=\"todo aquele que compete\">πᾶς ὁ ἀγωνιζόμενος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.25\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 9.25</a> (A. Ehrhardt, ZNW 48, 1957, 101–110); compare 2 Cl 7:1 ss.\n<span class=\"sense-number\">2.</span> Em geral, <strong>lutar, combater</strong>.\n<strong>a.</strong> Literalmente, com armas (Polyb. 1, 45, 9; Plut., <em>Marcell.</em> 303 [10, 4]; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/2MA.8.16\" target=\"_blank\" rel=\"noopener noreferrer\">2 Mc 8.16</a>): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἠγωνίζοντο ἄν, ἵνα μὴ παραδοθῶ\" data-meanings=\"lutariam para que eu não fosse entregue\">ἠγωνίζοντο ἄν, ἵνα μὴ παραδοθῶ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.36\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 18.36</a>.\n<strong>b.</strong> Figuradamente, de qualquer luta (<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"περὶ τῆς ἀληθείας\" data-meanings=\"pela verdade\">περὶ τῆς ἀληθείας</span> Orig., <em>C. Cels.</em> 1, 62, 63): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"κοπιῶ ἀγωνιζόμενος\" data-meanings=\"trabalho, esforçando-me\">κοπιῶ ἀγωνιζόμενος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.29\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 1.29</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Tm 4.10</a>. De luta na oração (Orig., <em>C. Cels.</em> 8, 73, 24): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀ. ὑπὲρ ὑμῶν\" data-meanings=\"lutar por vós\">ἀ. ὑπὲρ ὑμῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 4.12</a> (uso de <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀ. ὑπέρ τινος\" data-meanings=\"lutar por alguém\">ἀ. ὑπέρ τινος</span> em Diod S 13, 14, 3; SIG 317, 20; 386, 19; 409, 33; Jos., <em>Ant.</em> 13, 193). <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀ. ἀγῶνα\" data-meanings=\"combater o combate\">ἀ. ἀγῶνα</span> (veja <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγών\" data-meanings=\"combate\">ἀγών</span> 2), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Tm 6.12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Tm 4.7</a> (J. Barton, <em>Biblica</em> 40, 1959, 878–884). Com infinitivo seguinte (paralelos em Tucídides, Diodoro, papiros e autores cristãos), <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγωνίζεσθε εἰσελθεῖν\" data-meanings=\"esforçai-vos para entrar\">ἀγωνίζεσθε εἰσελθεῖν</span>, “empregai todo esforço para entrar”, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 13.24</a>; compare 1 Cl 35:4; <span class=\"biblio-ref tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"biblio\" data-tooltip-label=\"B 4:11\" data-tooltip-text=\"Epístola de Barnabé 4:11\">B 4:11</span>. — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄγω\" data-meanings=\"conduzir\">ἄγω</span>. M-M. TW.\n</p></section></article>"};
